+<!-- @dsCard group="Member Management" viewport="1180x920" name="Invite a member" subtitle="Member-admin and staff invite variants, mirrored from the shipped app" -->
+<!-- @startingPoint section="Member Management" subtitle="One-use email invitations from member and staff surfaces" viewport="1180x920" -->
+<!doctype html>
+<html lang="en" data-theme="light">
+<head>
+  <meta charset="utf-8">
+  <title>Invite a member · Memba</title>
+  <meta name="viewport" content="width=device-width, initial-scale=1">
+  <link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Figtree:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap">
+
+  <!-- daisyUI component CSS, prebuilt — renders the app's daisyUI components with no build step. -->
+  <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/daisyui@5">
+
+  <style>
+    /* Memba raw tokens (mirror of web/assets/css/app.css @theme). */
+    :root {
+      --color-sage-50:#eef1e6;
+      --color-sage-100:#dde3cf;
+      --color-sage-200:#bccaa6;
+      --color-sage-300:#98ab80;
+      --color-sage-400:#6f8760;
+      --color-sage-500:#5a7050;
+      --color-sage-600:#475a40;
+      --color-sage-700:#36462f;
+      --color-sage-800:#232e1e;
+
+      --color-cream:#f6f5ea;
+      --color-paper:#fffef9;
+      --color-apricot:#d2925a;
+      --color-apricot-soft:#f6e8d6;
+      --color-apricot-deep:#925f2e;
+
+      --color-ink:#25291d;
+      --color-ink-2:#555a47;
+      --color-ink-3:#878b76;
+
+      --color-line:#e8e6d4;
+      --color-line-strong:#d9d6bf;
+      --color-success:#5f7a4f;
+      --color-warning:#a8772e;
+      --color-error:#a8503a;
+      --color-info:#4f6b78;
+      --color-success-soft:#e9eedd;
+      --color-warning-soft:#f3ecd8;
+      --color-error-soft:#f1ddd3;
+      --color-info-soft:#e3e9ec;
+
+      --font-sans:"Figtree",ui-sans-serif,system-ui,sans-serif;
+      --font-mono:"JetBrains Mono",ui-monospace,SFMono-Regular,Menlo,monospace;
+    }
+
+    /* daisyUI "light" theme — copied from web/assets/css/app.css. */
+    :root {
+      color-scheme:light;
+      --color-base-100:#fffef9;
+      --color-base-200:#f6f5ea;
+      --color-base-300:#e8e6d4;
+      --color-base-content:#25291d;
+      --color-primary:#5a7050;
+      --color-primary-content:#f6f5ea;
+      --color-secondary:#555a47;
+      --color-secondary-content:#f6f5ea;
+      --color-accent:#d2925a;
+      --color-accent-content:#25291d;
+      --color-neutral:#25291d;
+      --color-neutral-content:#f6f5ea;
+      --color-info:#4f6b78;
+      --color-info-content:#f6f5ea;
+      --color-success:#5f7a4f;
+      --color-success-content:#f6f5ea;
+      --color-warning:#a8772e;
+      --color-warning-content:#f6f5ea;
+      --color-error:#a8503a;
+      --color-error-content:#f6f5ea;
+      --radius-selector:0.375rem;
+      --radius-field:0.375rem;
+      --radius-box:0.75rem;
+      --size-selector:0.25rem;
+      --size-field:0.25rem;
+      --border:1px;
+      --depth:0;
+      --noise:0;
+    }
+
+    * { box-sizing:border-box; }
+    html, body { margin:0; }
+    body {
+      min-height:100vh;
+      background:var(--color-base-200);
+      color:var(--color-base-content);
+      font-family:var(--font-sans);
+      -webkit-font-smoothing:antialiased;
+      text-rendering:optimizeLegibility;
+    }
+    a { color:inherit; text-decoration:none; }
+    h1, h2, h3, p { margin:0; }
+
+    .preview-shell {
+      display:grid;
+      gap:28px;
+      padding:28px;
+    }
+    .preview-title {
+      display:flex;
+      align-items:flex-end;
+      justify-content:space-between;
+      gap:18px;
+      max-width:1120px;
+      margin:0 auto;
+      width:100%;
+    }
+    .preview-title__eyebrow {
+      color:var(--color-ink-3);
+      font-size:12px;
+      font-weight:700;
+      letter-spacing:0.18em;
+      text-transform:uppercase;
+    }
+    .preview-title h1 {
+      color:var(--color-ink);
+      font-size:34px;
+      font-weight:700;
+      letter-spacing:-0.035em;
+      line-height:1.05;
+      margin-top:5px;
+    }
+    .preview-title p {
+      color:var(--color-ink-2);
+      font-size:14px;
+      line-height:1.45;
+      max-width:58ch;
+      margin-top:8px;
+    }
+    .variant-label {
+      border:1px solid var(--color-line-strong);
+      border-radius:999px;
+      color:var(--color-ink-2);
+      font-family:var(--font-mono);
+      font-size:11px;
+      padding:7px 10px;
+      white-space:nowrap;
+    }
+
+    .surface-grid {
+      display:grid;
+      gap:24px;
+      grid-template-columns:minmax(0, 1fr) minmax(0, 1fr);
+      max-width:1120px;
+      margin:0 auto;
+      width:100%;
+    }
+    .surface-card {
+      border:1px solid var(--color-line-strong);
+      border-radius:24px;
+      box-shadow:0 16px 40px rgba(37,41,29,0.08);
+      overflow:hidden;
+      background:var(--color-paper);
+      min-width:0;
+    }
+    .surface-caption {
+      background:var(--color-sage-800);
+      color:var(--color-cream);
+      display:flex;
+      align-items:center;
+      justify-content:space-between;
+      gap:14px;
+      padding:12px 16px;
+    }
+    .surface-caption strong {
+      font-size:13px;
+      font-weight:700;
+      letter-spacing:0.01em;
+    }
+    .surface-caption span {
+      color:rgba(246,245,234,0.68);
+      font-family:var(--font-mono);
+      font-size:10px;
+    }
+
+    .member-shell {
+      background:var(--color-base-200);
+      color:var(--color-base-content);
+      min-height:760px;
+    }
+    .member-topbar {
+      background:var(--color-base-100);
+      border-bottom:1px solid var(--color-base-300);
+      display:flex;
+      align-items:center;
+      justify-content:space-between;
+      gap:16px;
+      padding:16px 20px;
+    }
+    .club-name {
+      color:var(--color-base-content);
+      font-size:18px;
+      font-weight:650;
+      letter-spacing:-0.02em;
+    }
+    .member-nav {
+      display:flex;
+      align-items:center;
+      gap:10px;
+      color:var(--color-ink-2);
+      font-size:13px;
+      font-weight:500;
+    }
+    .member-main {
+      padding:32px 24px 38px;
+    }
+    .member-stack {
+      display:grid;
+      gap:28px;
+      margin:0 auto;
+      max-width:700px;
+    }
+
+    .panel {
+      background:var(--color-base-100);
+      border:1px solid var(--color-base-300);
+      border-radius:24px;
+      box-shadow:0 1px 2px rgba(37,41,29,0.04);
+      overflow:hidden;
+    }
+    .panel--hero {
+      padding:26px;
+    }
+    .back-link {
+      align-items:center;
+      color:var(--color-ink-2);
+      display:inline-flex;
+      font-size:14px;
+      font-weight:700;
+      gap:8px;
+    }
+    .eyebrow {
+      color:var(--color-ink-2);
+      font-size:12px;
+      font-weight:700;
+      letter-spacing:0.18em;
+      margin-top:24px;
+      text-transform:uppercase;
+    }
+    .hero-title {
+      color:var(--color-base-content);
+      font-size:38px;
+      font-weight:650;
+      letter-spacing:-0.04em;
+      line-height:1.05;
+      margin-top:8px;
+    }
+    .club-kicker {
+      color:var(--color-primary);
+      font-size:13px;
+      font-weight:700;
+      letter-spacing:0.18em;
+      margin-top:13px;
+      text-transform:uppercase;
+    }
+    .body-copy {
+      color:var(--color-ink-2);
+      font-size:16px;
+      line-height:1.65;
+      margin-top:20px;
+    }
+    .current-member {
+      align-items:center;
+      background:var(--color-base-200);
+      border:1px solid var(--color-base-300);
+      border-radius:18px;
+      display:flex;
+      gap:12px;
+      margin-top:24px;
+      padding:13px 15px;
+    }
+    .avatar-circle {
+      align-items:center;
+      background:var(--color-sage-200);
+      border-radius:999px;
+      color:var(--color-sage-800);
+      display:inline-flex;
+      flex:none;
+      font-size:13px;
+      font-weight:700;
+      height:36px;
+      justify-content:center;
+      width:36px;
+    }
+    .current-member strong {
+      color:var(--color-base-content);
+      display:block;
+      font-size:14px;
+      font-weight:700;
+      line-height:1.2;
+    }
+    .current-member span {
+      color:var(--color-ink-2);
+      display:block;
+      font-size:12px;
+      margin-top:3px;
+    }
+
+    .form-head {
+      border-bottom:1px solid var(--color-base-300);
+      padding:20px;
+    }
+    .form-head .eyebrow,
+    .admin-form-head .admin-eyebrow {
+      margin-top:0;
+    }
+    .form-title {
+      color:var(--color-base-content);
+      font-size:18px;
+      font-weight:700;
+      letter-spacing:-0.02em;
+      margin-top:5px;
+    }
+    .form-intro {
+      color:var(--color-ink-2);
+      font-size:14px;
+      line-height:1.5;
+      margin-top:5px;
+    }
+    .invite-form {
+      display:grid;
+      gap:20px;
+      padding:20px;
+    }
+    .input-box {
+      background:var(--color-base-200);
+      border:1px solid var(--color-base-300);
+      border-radius:18px;
+      padding:16px;
+    }
+    .field-label {
+      color:var(--color-base-content);
+      display:block;
+      font-size:14px;
+      font-weight:650;
+      margin-bottom:7px;
+    }
+    .input {
+      width:100%;
+    }
+    .form-actions {
+      display:flex;
+      flex-wrap:wrap;
+      gap:12px;
+    }
+    .state-row {
+      display:grid;
+      gap:9px;
+      margin-top:2px;
+    }
+    .state-row .alert {
+      align-items:flex-start;
+      border-radius:14px;
+      font-size:13px;
+      line-height:1.35;
+      padding:10px 12px;
+    }
+    .field-error {
+      color:var(--color-error);
+      font-size:13px;
+      line-height:1.35;
+      margin-top:8px;
+    }
+
+    .admin-shell {
+      background:#f7f6f3;
+      color:#15201c;
+      display:grid;
+      grid-template-columns:190px minmax(0, 1fr);
+      min-height:760px;
+    }
+    .admin-sidebar {
+      background:#102019;
+      color:white;
+      display:flex;
+      flex-direction:column;
+      padding:18px 12px;
+    }
+    .staff-brand {
+      align-items:center;
+      display:flex;
+      gap:9px;
+      padding:0 4px;
+    }
+    .brand-mark {
+      align-items:center;
+      background:#24574d;
+      border-radius:8px;
+      color:white;
+      display:inline-flex;
+      font-weight:800;
+      height:28px;
+      justify-content:center;
+      width:28px;
+    }
+    .staff-brand strong {
+      color:white;
+      font-size:16px;
+      letter-spacing:-0.02em;
+    }
+    .staff-chip {
+      background:#6b614b;
+      border-radius:999px;
+      color:#eee6cf;
+      font-size:10px;
+      font-weight:800;
+      letter-spacing:0.16em;
+      padding:3px 7px;
+      text-transform:uppercase;
+    }
+    .admin-nav {
+      display:grid;
+      gap:22px;
+      margin-top:34px;
+    }
+    .admin-nav-group {
+      display:grid;
+      gap:8px;
+    }
+    .admin-nav-title {
+      color:rgba(255,255,255,0.45);
+      font-size:11px;
+      font-weight:800;
+      letter-spacing:0.18em;
+      padding:0 8px;
+      text-transform:uppercase;
+    }
+    .admin-nav-link {
+      border-radius:9px;
+      color:rgba(255,255,255,0.75);
+      font-size:14px;
+      font-weight:600;
+      padding:10px 12px;
+    }
+    .admin-nav-link--active {
+      background:#1f574e;
+      color:white;
+      box-shadow:0 1px 2px rgba(0,0,0,0.14);
+    }
+    .staff-identity {
+      border-top:1px solid rgba(255,255,255,0.1);
+      display:flex;
+      gap:10px;
+      margin-top:auto;
+      padding:14px 8px 0;
+    }
+    .staff-avatar {
+      align-items:center;
+      background:#2f6257;
+      border-radius:999px;
+      color:white;
+      display:flex;
+      flex:none;
+      font-size:12px;
+      font-weight:800;
+      height:32px;
+      justify-content:center;
+      width:32px;
+    }
+    .staff-identity strong {
+      color:white;
+      display:block;
+      font-size:13px;
+      line-height:1.2;
+      overflow:hidden;
+      text-overflow:ellipsis;
+      white-space:nowrap;
+      max-width:110px;
+    }
+    .staff-identity span {
+      color:rgba(255,255,255,0.5);
+      display:block;
+      font-size:12px;
+      margin-top:3px;
+    }
+    .admin-content {
+      min-width:0;
+      padding:28px;
+    }
+    .admin-main {
+      display:grid;
+      gap:24px;
+      max-width:760px;
+      margin:0 auto;
+    }
+    .admin-header {
+      display:flex;
+      gap:20px;
+      justify-content:space-between;
+      align-items:flex-start;
+    }
+    .admin-header-copy {
+      display:grid;
+      gap:10px;
+      min-width:0;
+    }
+    .admin-back {
+      color:#1f4842;
+      font-size:14px;
+      font-weight:700;
+    }
+    .admin-eyebrow {
+      color:#7d877f;
+      font-size:12px;
+      font-weight:750;
+      letter-spacing:0.12em;
+      text-transform:uppercase;
+    }
+    .admin-header h2 {
+      color:#15201c;
+      font-size:32px;
+      font-weight:800;
+      letter-spacing:-0.035em;
+      line-height:1.05;
+    }
+    .admin-copy {
+      color:#4b5a55;
+      font-size:15px;
+      line-height:1.55;
+      max-width:58ch;
+    }
+    .context-card {
+      background:white;
+      border:1px solid #e6e3dc;
+      border-radius:16px;
+      box-shadow:0 1px 2px rgba(21,32,28,0.06);
+      flex:0 0 210px;
+      padding:16px;
+    }
+    .context-card strong {
+      color:#15201c;
+      display:block;
+      font-size:18px;
+      letter-spacing:-0.02em;
+      margin-top:9px;
+    }
+    .context-card code {
+      color:#7d877f;
+      display:block;
+      font-family:var(--font-mono);
+      font-size:11px;
+      line-height:1.4;
+      margin-top:5px;
+      word-break:break-all;
+    }
+    .admin-panel {
+      background:white;
+      border:1px solid #e6e3dc;
+      border-radius:18px;
+      box-shadow:0 1px 2px rgba(21,32,28,0.06);
+      overflow:hidden;
+    }
+    .admin-form-head {
+      border-bottom:1px solid #e6e3dc;
+      padding:20px;
+    }
+    .admin-form-head h3 {
+      color:#15201c;
+      font-size:18px;
+      font-weight:750;
+      margin-top:5px;
+    }
+    .admin-form-head p {
+      color:#7d877f;
+      font-size:14px;
+      line-height:1.5;
+      margin-top:5px;
+    }
+    .admin-form {
+      display:grid;
+      gap:20px;
+      padding:20px;
+    }
+    .admin-input-box {
+      background:#f7f6f3;
+      border:1px solid #e6e3dc;
+      border-radius:16px;
+      padding:16px;
+    }
+    .admin-button-primary {
+      background:#1f4842;
+      border-color:#1f4842;
+      color:white;
+    }
+    .admin-button-secondary {
+      background:white;
+      border-color:#d6d2c8;
+      color:#4b5a55;
+    }
+    .missing-club-note {
+      background:#fffaf1;
+      border:1px solid #eadfc9;
+      border-radius:16px;
+      color:#6b614b;
+      font-size:13px;
+      line-height:1.45;
+      padding:13px 15px;
+    }
+    .missing-club-note strong {
+      color:#15201c;
+      display:block;
+      font-size:14px;
+      margin-bottom:3px;
+    }
+
+    @media (max-width: 980px) {
+      .surface-grid {
+        grid-template-columns:1fr;
+      }
+      .preview-title {
+        align-items:flex-start;
+        flex-direction:column;
+      }
