+              data-current-member-id="member_lou_thirgood"
+              data-active-member-count="142"
+              class="member-stack"
+            >
+              <section class="panel panel--hero">
+                <a id="member-club-invitation-club-home-link" href="#" class="back-link">← Club home</a>
+
+                <p class="eyebrow">Member invitations</p>
+                <h2 class="hero-title">Invite a member</h2>
+                <p
+                  id="member-club-invitation-selected-club"
+                  data-club-id="club_kootenay_alpine"
+                  class="club-kicker"
+                >
+                  Kootenay Alpine Club
+                </p>
+                <p class="body-copy">
+                  Send a one-use invitation link for Kootenay Alpine Club. The invitation
+                  stays scoped to this club, and invited people will become ordinary members
+                  after they accept.
+                </p>
+
+                <div
+                  id="member-club-invitation-current-member"
+                  data-current-member-id="member_lou_thirgood"
+                  class="current-member"
+                >
+                  <span
+                    id="member-club-invitation-current-member-avatar"
+                    data-testid="member-club-invitation-current-member-avatar"
+                    class="avatar-circle"
+                    title="Lou Thirgood"
+                  >
+                    LT
+                  </span>
+                  <span>
+                    <strong>Lou Thirgood</strong>
+                    <span>Inviting from this club membership</span>
+                  </span>
+                </div>
+              </section>
+
+              <section id="member-club-invitation-form-card" class="panel">
+                <div class="form-head">
+                  <p class="eyebrow">Invitation details</p>
+                  <h3 class="form-title">Email-only member invitation</h3>
+                  <p class="form-intro">
+                    Enter the invitee's email address. Memba sends a one-use link so the
+                    invited person controls that email before membership starts.
+                  </p>
+                </div>
+
+                <form id="member-club-invitation-form" aria-label="Invite member" class="invite-form">
+                  <div class="input-box">
+                    <label for="member-club-invitation-email-input" class="field-label">Email address</label>
+                    <input
+                      id="member-club-invitation-email-input"
+                      class="input"
+                      type="email"
+                      name="invitation[email]"
+                      aria-label="Invitee email address"
+                      autocomplete="email"
+                      placeholder="dana@example.com"
+                      required
+                    >
+                  </div>
+
+                  <div class="form-actions">
+                    <button id="send-member-club-invitation-button" class="btn btn-primary btn-lg" type="submit" aria-label="Send member invitation">
+                      Send invitation
+                    </button>
+                    <a id="cancel-member-club-invitation-link" href="#" class="btn btn-soft btn-lg" aria-label="Cancel member invitation">
+                      Cancel
+                    </a>
+                  </div>
+
+                  <div class="state-row" aria-label="Member invite feedback states">
+                    <div class="alert alert-info">Invitation sent to dana@example.com</div>
+                    <div class="alert alert-error">That email address is already an active member of this club.</div>
+                  </div>
+                </form>
+              </section>
+            </div>
+          </main>
+        </div>
+      </article>
+
+      <article class="surface-card">
+        <div class="surface-caption">
+          <strong>Staff invitation</strong>
+          <span>/admin/clubs/:club_id/invitations/new</span>
+        </div>
+
+        <div id="admin-layout" data-surface="admin" class="admin-shell">
+          <aside id="admin-sidebar" class="admin-sidebar">
+            <a href="#" class="staff-brand" aria-label="Memba staff home">
+              <span class="brand-mark">m</span>
+              <strong>Memba</strong>
+              <span class="staff-chip">Staff</span>
+            </a>
+
+            <nav class="admin-nav" aria-label="Memba staff navigation">
+              <div class="admin-nav-group">
+                <p class="admin-nav-title">Operations</p>
+                <a href="#" class="admin-nav-link admin-nav-link--active">Clubs</a>
+                <a href="#" class="admin-nav-link">Requests</a>
+                <a href="#" class="admin-nav-link">People</a>
+              </div>
+              <div class="admin-nav-group">
+                <p class="admin-nav-title">Messaging</p>
+                <a href="#" class="admin-nav-link">Messages</a>
+                <a href="#" class="admin-nav-link">Deliveries</a>
+              </div>
+            </nav>
+
+            <div id="admin-staff-identity-block" class="staff-identity">
+              <span class="staff-avatar">MS</span>
+              <span>
+                <strong>staff@memba.test</strong>
+                <span>Signed in</span>
+              </span>
+            </div>
+          </aside>
+
+          <div id="admin-content" class="admin-content">
+            <main
+              id="club-member-invitation-new"
+              data-admin-page="club-member-invitation-new"
+              data-club-id="club_kootenay_alpine"
+              class="admin-main"
+            >
+              <section id="club-member-invitation-page-header" class="admin-header">
+                <div class="admin-header-copy">
+                  <a id="back-to-club-link" href="#" aria-label="Back to club" class="admin-back">← Club</a>
+                  <p class="admin-eyebrow">Member invitations</p>
+                  <h2>Invite a member</h2>
+                  <p class="admin-copy">
+                    Send a one-use invitation link for Kootenay Alpine Club. The invitee controls
+                    the email address and will enter their own profile details before membership starts.
+                  </p>
+                </div>
+
+                <div id="club-member-invitation-context-card" class="context-card">
+                  <p class="admin-eyebrow">Club context</p>
+                  <strong>Kootenay Alpine Club</strong>
+                  <code>club_kootenay_alpine</code>
+                </div>
+              </section>
+
+              <section id="club-member-invitation-form-card" class="admin-panel">
+                <div class="admin-form-head">
+                  <p class="admin-eyebrow">Invitation details</p>
+                  <h3>Email-only member invitation</h3>
+                  <p>
+                    Staff provide only the email address. Memba will not create a person record
+                    or an active club membership until the invitee accepts and completes profile details.
+                  </p>
+                </div>
+
+                <form id="club-member-invitation-form" aria-label="Invite member" class="admin-form">
+                  <div class="admin-input-box">
+                    <label for="club-member-invitation-email-input" class="field-label">Email address</label>
+                    <input
+                      id="club-member-invitation-email-input"
+                      class="input input-error"
+                      type="email"
+                      name="invitation[email]"
+                      aria-label="Invitee email address"
+                      autocomplete="email"
+                      value="robin"
+                      placeholder="robin@example.com"
+                      required
+                    >
+                    <p class="field-error">Enter a valid email address.</p>
+                  </div>
+
+                  <div class="form-actions">
+                    <button id="send-club-member-invitation-button" class="btn btn-lg admin-button-primary" type="submit" aria-label="Send member invitation">
+                      Send invitation
+                    </button>
+                    <a id="cancel-club-member-invitation-link" href="#" class="btn btn-lg admin-button-secondary" aria-label="Cancel member invitation">
+                      Cancel
+                    </a>
+                  </div>
+
+                  <div class="state-row" aria-label="Staff invite feedback states">
+                    <div class="alert alert-info">Invitation resent to robin@example.com</div>
+                    <div class="alert alert-error">Invitation was created, but Memba could not send the email. Try again.</div>
+                  </div>
+                </form>
+              </section>
+
+              <section class="missing-club-note" aria-label="Missing club state">
+                <strong>Missing club state</strong>
+                If the club projection is missing, this surface shows “Club not found” with
+                “No projected club exists for this URL.” and a “← Clubs” back link.
+              </section>
+            </main>
+          </div>
+        </div>
+      </article>
+    </div>
+  </div>
+</body>
+</html>
