+++ b/design-system/wireframes/profile-completion.html
@@ -0,0 +1,610 @@
+<!-- @dsCard group="Member Management" viewport="1180x920" name="Profile completion" subtitle="Invited club member completes their name before membership starts" -->
+<!-- @startingPoint section="Member Management" subtitle="Accepted invitees create their member profile with name + verified email" viewport="1180x920" -->
+<!doctype html>
+<html lang="en" data-theme="light">
+<head>
+  <meta charset="utf-8">
+  <title>Profile completion · Memba</title>
+  <meta name="viewport" content="width=device-width, initial-scale=1">
+  <link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Figtree:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap">
+
+  <!-- daisyUI component CSS, prebuilt — renders the app's daisyUI components with no build step. -->
+  <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/daisyui@5">
+
+  <style>
+    /* Memba raw tokens (mirror of web/assets/css/app.css @theme). */
+    :root {
+      --color-sage-50:#eef1e6;
+      --color-sage-100:#dde3cf;
+      --color-sage-200:#bccaa6;
+      --color-sage-300:#98ab80;
+      --color-sage-400:#6f8760;
+      --color-sage-500:#5a7050;
+      --color-sage-600:#475a40;
+      --color-sage-700:#36462f;
+      --color-sage-800:#232e1e;
+
+      --color-cream:#f6f5ea;
+      --color-paper:#fffef9;
+      --color-apricot:#d2925a;
+      --color-apricot-soft:#f6e8d6;
+      --color-apricot-deep:#925f2e;
+
+      --color-ink:#25291d;
+      --color-ink-2:#555a47;
+      --color-ink-3:#878b76;
+
+      --color-line:#e8e6d4;
+      --color-line-strong:#d9d6bf;
+      --color-success:#5f7a4f;
+      --color-warning:#a8772e;
+      --color-error:#a8503a;
+      --color-info:#4f6b78;
+      --color-success-soft:#e9eedd;
+      --color-warning-soft:#f3ecd8;
+      --color-error-soft:#f1ddd3;
+      --color-info-soft:#e3e9ec;
+
+      --font-sans:"Figtree",ui-sans-serif,system-ui,sans-serif;
+      --font-mono:"JetBrains Mono",ui-monospace,SFMono-Regular,Menlo,monospace;
+    }
+
+    /* daisyUI "light" theme — copied from web/assets/css/app.css. */
+    :root {
+      color-scheme:light;
+      --color-base-100:#fffef9;
+      --color-base-200:#f6f5ea;
+      --color-base-300:#e8e6d4;
+      --color-base-content:#25291d;
+      --color-primary:#5a7050;
+      --color-primary-content:#f6f5ea;
+      --color-secondary:#555a47;
+      --color-secondary-content:#f6f5ea;
+      --color-accent:#d2925a;
+      --color-accent-content:#25291d;
+      --color-neutral:#25291d;
+      --color-neutral-content:#f6f5ea;
+      --color-info:#4f6b78;
+      --color-info-content:#f6f5ea;
+      --color-success:#5f7a4f;
+      --color-success-content:#f6f5ea;
+      --color-warning:#a8772e;
+      --color-warning-content:#f6f5ea;
+      --color-error:#a8503a;
+      --color-error-content:#f6f5ea;
+      --radius-selector:0.375rem;
+      --radius-field:0.375rem;
+      --radius-box:0.75rem;
+      --size-selector:0.25rem;
+      --size-field:0.25rem;
+      --border:1px;
+      --depth:0;
+      --noise:0;
+    }
+
+    * { box-sizing:border-box; }
+    html, body { margin:0; }
+    body {
+      min-height:100vh;
+      background:var(--color-base-200);
+      color:var(--color-base-content);
+      font-family:var(--font-sans);
+      -webkit-font-smoothing:antialiased;
+      text-rendering:optimizeLegibility;
+    }
+    a { color:inherit; text-decoration:none; }
+    h1, h2, h3, p { margin:0; }
+
+    .preview-shell {
+      display:grid;
+      gap:28px;
+      padding:28px;
+    }
+    .preview-title {
+      display:flex;
+      align-items:flex-end;
+      justify-content:space-between;
+      gap:18px;
+      max-width:1120px;
+      margin:0 auto;
+      width:100%;
+    }
+    .preview-title__eyebrow {
+      color:var(--color-ink-3);
+      font-size:12px;
+      font-weight:700;
+      letter-spacing:0.18em;
+      text-transform:uppercase;
+    }
+    .preview-title h1 {
+      color:var(--color-ink);
+      font-size:34px;
+      font-weight:700;
+      letter-spacing:-0.035em;
+      line-height:1.05;
+      margin-top:5px;
+    }
+    .preview-title p {
+      color:var(--color-ink-2);
+      font-size:14px;
+      line-height:1.45;
+      max-width:62ch;
+      margin-top:8px;
+    }
+    .variant-label {
+      border:1px solid var(--color-line-strong);
+      border-radius:999px;
+      color:var(--color-ink-2);
+      font-family:var(--font-mono);
+      font-size:11px;
+      padding:7px 10px;
+      white-space:nowrap;
+    }
+
+    .surface-grid {
+      display:grid;
+      gap:24px;
+      grid-template-columns:minmax(0, 1fr) minmax(0, 1fr);
+      max-width:1120px;
+      margin:0 auto;
+      width:100%;
+    }
+    .surface-card {
+      background:var(--color-paper);
+      border:1px solid var(--color-line-strong);
+      border-radius:24px;
+      box-shadow:0 16px 40px rgba(37,41,29,0.08);
+      min-width:0;
+      overflow:hidden;
+    }
+    .surface-caption {
+      background:var(--color-sage-800);
+      color:var(--color-cream);
+      display:flex;
+      align-items:center;
+      justify-content:space-between;
+      gap:14px;
+      padding:12px 16px;
+    }
+    .surface-caption strong {
+      font-size:13px;
+      font-weight:700;
+      letter-spacing:0.01em;
+    }
+    .surface-caption span {
+      color:rgba(246,245,234,0.68);
+      font-family:var(--font-mono);
+      font-size:10px;
+    }
+
+    .app-chrome {
+      background:var(--color-base-200);
+      min-height:690px;
+      position:relative;
+    }
+    .app-header {
+      background:var(--color-paper);
+      border-bottom:1px solid var(--color-line);
+      padding:16px 22px;
+    }
+    .app-header__inner {
+      align-items:center;
+      display:flex;
+      gap:18px;
+      justify-content:space-between;
+      margin:0 auto;
+      max-width:920px;
+    }
+    .brand-link {
+      align-items:center;
+      display:inline-flex;
+      gap:10px;
+      transition:opacity 160ms ease;
+      width:max-content;
+    }
+    .brand-link:hover { opacity:0.82; }
+    .sprig {
+      color:var(--color-sage-600);
+      display:block;
+      height:28px;
+      width:28px;
+    }
+    .wordmark {
