+  <main class="card-shell" aria-label="Badge component examples">
+    <div class="row" aria-label="Status badge examples">
+      <span class="lbl">status</span>
+      <span class="badge badge-success badge-soft"><span class="dot"></span>Active</span>
+      <span class="badge badge-info badge-soft"><span class="dot"></span>Trial</span>
+      <span class="badge badge-warning badge-soft"><span class="dot"></span>Paused</span>
+      <span class="badge badge-error badge-soft"><span class="dot"></span>Bounced</span>
+    </div>
+
+    <div class="sep"></div>
+
+    <div class="row" aria-label="Club role badge examples">
+      <span class="lbl">roles</span>
+      <span class="badge badge-primary badge-soft">Chair</span>
+      <span class="badge badge-primary badge-soft">Trip leader</span>
+      <span class="badge badge-info badge-soft">Safeguarding officer</span>
+      <span class="badge badge-neutral badge-soft">Member</span>
+    </div>
+
+    <div class="sep"></div>
+
+    <div class="row" aria-label="Membership administration badge examples">
+      <span class="lbl">member admin</span>
+      <span class="badge badge-primary badge-soft">Admin</span>
+      <span class="badge badge-primary badge-soft">Membership Administrator</span>
+      <span class="hint">built-in role + business-language label</span>
+    </div>
+
+    <div class="sep"></div>
+
+    <div class="row" aria-label="Membership chip examples">
+      <span class="lbl">membership</span>
+      <span class="membership-chip">Active membership</span>
+      <span class="slug-chip">west-coast-paddlers</span>
+      <span class="hint">mirrors the shipped club-admin table chips</span>
+    </div>
+  </main>
+</body>
+</html>
